UPDATE focus_routines SET title=#{title},project_id=#{projectId},weekdays=#{weekdays},
    default_duration_minutes=#{duration},enabled=#{enabled},version=version+1,updated_at=#{now}
WHERE id=#{id} AND user_id=#{userId} AND version=#{version}

mapper.insert:
INSERT INTO focus_intervals(session_id,user_id,ordinal,kind,start_at,end_at,confirmed)
SELECT #{sessionId},#{userId},COALESCE(MAX(ordinal),0)+1,#{kind},#{start},#{end},#{confirmed}
FROM focus_intervals WHERE session_id=#{sessionId}
HAVING #{end} > #{start}
